import{c as t,Q as e,j as i,m as r}from"./chunks/framework.BnKG8mJY.js";const c=JSON.parse('{"title":"Admin Guide","description":"","frontmatter":{"title":"Admin Guide","outline":"deep"},"headers":[],"relativePath":"guide/admin-guide.md","filePath":"guide/admin-guide.md"}'),n={name:"guide/admin-guide.md"};function o(l,a,s,d,u,h){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="admin-guide" tabindex="-1">Admin Guide <a class="header-anchor" href="#admin-guide" aria-label="Permalink to &quot;Admin Guide&quot;">​</a></h1><p>Panduan khusus untuk administrator sistem TMS. Admin memiliki akses penuh ke semua modul termasuk Master Data dan manajemen pengguna.</p><h2 id="peran-admin" tabindex="-1">Peran Admin <a class="header-anchor" href="#peran-admin" aria-label="Permalink to &quot;Peran Admin&quot;">​</a></h2><ul><li>Mengelola seluruh master data (truck, driver, customer, area, warehouse, subcont, admin)</li><li>Mengelola transaksi (Sales Cost, Subcontractor, Repair)</li><li>Mengelola user dan hak akses</li><li>Monitoring armada dan GPS</li><li>Import/export data bulk</li><li>Aktivasi/deaktivasi truck dan driver</li></ul><h2 id="master-data" tabindex="-1">Master Data <a class="header-anchor" href="#master-data" aria-label="Permalink to &quot;Master Data&quot;">​</a></h2><h3 id="master-truck" tabindex="-1">Master Truck <a class="header-anchor" href="#master-truck" aria-label="Permalink to &quot;Master Truck&quot;">​</a></h3><p><strong>Path:</strong> <code>/master/trucks</code></p><h4 id="fitur" tabindex="-1">Fitur <a class="header-anchor" href="#fitur" aria-label="Permalink to &quot;Fitur&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Aksi</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Tambah Truck</td><td>Input data truck baru</td></tr><tr><td>Edit</td><td>Ubah data truck existing</td></tr><tr><td>Import Excel</td><td>Import bulk dari template</td></tr><tr><td>Auto Mapping Wialon</td><td>Otomatis mapping truck ke unit GPS Wialon</td></tr><tr><td>Aktifkan/Nonaktifkan</td><td>Soft disable truck dari operasional</td></tr><tr><td>Hapus</td><td>Hard delete (permanen)</td></tr></tbody></table><h4 id="field-data" tabindex="-1">Field Data <a class="header-anchor" href="#field-data" aria-label="Permalink to &quot;Field Data&quot;">​</a></h4><ul><li>Jenis Kendaraan</li><li>No Police (plat nomor)</li><li>Wialon Unit ID (mapping GPS)</li><li>Merk Mobil</li><li>Model</li><li>Type Truck</li></ul><h4 id="status-aktif-nonaktif" tabindex="-1">Status Aktif/Nonaktif <a class="header-anchor" href="#status-aktif-nonaktif" aria-label="Permalink to &quot;Status Aktif/Nonaktif&quot;">​</a></h4><ul><li><strong>Aktif</strong>: Muncul di dropdown operasional, GPS map, dan bisa digunakan transaksi baru</li><li><strong>Nonaktif</strong>: Tetap muncul di Master Truck, tetap muncul di historical records, tapi tidak muncul di dropdown operasional dan GPS</li></ul><blockquote><p><strong>Penting:</strong> Gunakan Nonaktifkan (bukan Hapus) jika truck masih punya historical records yang perlu ditampilkan.</p></blockquote><h3 id="master-driver" tabindex="-1">Master Driver <a class="header-anchor" href="#master-driver" aria-label="Permalink to &quot;Master Driver&quot;">​</a></h3><p><strong>Path:</strong> <code>/master/drivers</code></p><p>Sama seperti Master Truck dengan field:</p><ul><li>Nama Supir</li><li>Alamat</li><li>No HP</li><li>Status aktif/nonaktif</li></ul><h4 id="status-aktif-nonaktif-driver" tabindex="-1">Status Aktif/Nonaktif Driver <a class="header-anchor" href="#status-aktif-nonaktif-driver" aria-label="Permalink to &quot;Status Aktif/Nonaktif Driver&quot;">​</a></h4><ul><li><strong>Aktif</strong>: Muncul di dropdown Sales Cost, template import, Data Supir</li><li><strong>Nonaktif</strong>: Tetap di Master Driver, tetap di historical records, tidak muncul di operasional</li></ul><h3 id="master-customer" tabindex="-1">Master Customer <a class="header-anchor" href="#master-customer" aria-label="Permalink to &quot;Master Customer&quot;">​</a></h3><p><strong>Path:</strong> <code>/master/customers</code></p><p>Field: Nama Customer, Alamat, Kontak.</p><h3 id="master-area" tabindex="-1">Master Area <a class="header-anchor" href="#master-area" aria-label="Permalink to &quot;Master Area&quot;">​</a></h3><p><strong>Path:</strong> <code>/master/areas</code></p><p>Field:</p><ul><li>Kode Area</li><li>Nama Area (auto-generated dari route steps)</li><li>Route Steps (urutan geofence Wialon untuk tracking)</li><li>Finish Geofence (geofence akhir untuk menandai selesai)</li></ul><h4 id="route-step-configuration" tabindex="-1">Route Step Configuration <a class="header-anchor" href="#route-step-configuration" aria-label="Permalink to &quot;Route Step Configuration&quot;">​</a></h4><p>Area bisa dikonfigurasi dengan route steps yang di-mapping ke geofence Wialon. Ini memungkinkan tracking otomatis progress pengiriman.</p><h3 id="master-warehouse" tabindex="-1">Master Warehouse <a class="header-anchor" href="#master-warehouse" aria-label="Permalink to &quot;Master Warehouse&quot;">​</a></h3><p><strong>Path:</strong> <code>/master/warehouses</code></p><p>Field: Nama Warehouse, Alamat.</p><h3 id="master-subcont" tabindex="-1">Master Subcont <a class="header-anchor" href="#master-subcont" aria-label="Permalink to &quot;Master Subcont&quot;">​</a></h3><p><strong>Path:</strong> <code>/master/subconts</code></p><p>Field: Nama Subcontractor, Alamat, Kontak.</p><h3 id="master-admin" tabindex="-1">Master Admin <a class="header-anchor" href="#master-admin" aria-label="Permalink to &quot;Master Admin&quot;">​</a></h3><p><strong>Path:</strong> <code>/master/admins</code></p><p>Mengelola akun pengguna sistem.</p><p>Field:</p><ul><li>Username</li><li>Password</li><li>Level (admin / user / mekanik / cs)</li><li>Nama</li><li>Foto profil</li></ul><h4 id="level-pengguna" tabindex="-1">Level Pengguna <a class="header-anchor" href="#level-pengguna" aria-label="Permalink to &quot;Level Pengguna&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Level</th><th>Akses</th></tr></thead><tbody><tr><td><code>admin</code></td><td>Semua fitur</td></tr><tr><td><code>user</code></td><td>Semua kecuali Master Data dan edit Repair</td></tr><tr><td><code>mekanik</code></td><td>Dashboard, Data Transport, Repair only</td></tr><tr><td><code>cs</code></td><td>Schedule Pengiriman dan Profile only</td></tr></tbody></table><h2 id="import-export-data" tabindex="-1">Import &amp; Export Data <a class="header-anchor" href="#import-export-data" aria-label="Permalink to &quot;Import &amp; Export Data&quot;">​</a></h2><h3 id="import-excel" tabindex="-1">Import Excel <a class="header-anchor" href="#import-excel" aria-label="Permalink to &quot;Import Excel&quot;">​</a></h3><p>Tersedia di: Master Truck, Master Driver, Sales Cost</p><ol><li>Klik <strong>Import Excel</strong></li><li>Download template terlebih dahulu (jika belum punya)</li><li>Isi data sesuai format template</li><li>Upload file Excel</li><li>Sistem akan validasi dan import data</li></ol><blockquote><p><strong>Catatan:</strong> Import Sales Cost akan reject truck/driver yang nonaktif.</p></blockquote><h3 id="export-excel" tabindex="-1">Export Excel <a class="header-anchor" href="#export-excel" aria-label="Permalink to &quot;Export Excel&quot;">​</a></h3><p>Tersedia di: Sales Cost, Subcontractor, Data Truck, Data Chasis, Data Supir, KM Bulanan Truk</p><p>Klik <strong>Export Excel</strong> untuk download data yang sedang ditampilkan (sesuai filter aktif).</p><h2 id="manajemen-transaksi" tabindex="-1">Manajemen Transaksi <a class="header-anchor" href="#manajemen-transaksi" aria-label="Permalink to &quot;Manajemen Transaksi&quot;">​</a></h2><h3 id="sales-cost" tabindex="-1">Sales Cost <a class="header-anchor" href="#sales-cost" aria-label="Permalink to &quot;Sales Cost&quot;">​</a></h3><h4 id="membuat-transaksi-baru" tabindex="-1">Membuat Transaksi Baru <a class="header-anchor" href="#membuat-transaksi-baru" aria-label="Permalink to &quot;Membuat Transaksi Baru&quot;">​</a></h4><ol><li>Klik <strong>Tambah Transaksi</strong> atau buka <code>/sales-cost/new</code></li><li>Isi data: Truck, Driver, Customer, Area, tanggal delivery/arrival</li><li>Isi data biaya: Price, Ops Cost, dll</li><li>Simpan</li></ol><h4 id="edit-transaksi" tabindex="-1">Edit Transaksi <a class="header-anchor" href="#edit-transaksi" aria-label="Permalink to &quot;Edit Transaksi&quot;">​</a></h4><ul><li>Bisa mengubah semua field</li><li>Truck/driver nonaktif yang sudah ter-assign tetap bisa dipertahankan</li><li>Tapi tidak bisa ganti ke truck/driver nonaktif lain</li></ul><h4 id="print-spk" tabindex="-1">Print SPK <a class="header-anchor" href="#print-spk" aria-label="Permalink to &quot;Print SPK&quot;">​</a></h4><ul><li><strong>Single</strong>: Klik aksi Print pada baris transaksi</li><li><strong>Bulk</strong>: Centang beberapa transaksi → klik <strong>Cetak Terpilih</strong></li></ul><h4 id="detail-dengan-route-history" tabindex="-1">Detail dengan Route History <a class="header-anchor" href="#detail-dengan-route-history" aria-label="Permalink to &quot;Detail dengan Route History&quot;">​</a></h4><p>Jika area punya route steps dan truck punya GPS mapping, detail Sales Cost menampilkan:</p><ul><li>Planned route steps</li><li>Visited steps (dengan timestamp)</li><li>Pending steps</li><li>Badge untuk kunjungan out-of-order</li></ul><h3 id="subcontractor" tabindex="-1">Subcontractor <a class="header-anchor" href="#subcontractor" aria-label="Permalink to &quot;Subcontractor&quot;">​</a></h3><p>CRUD transaksi subcontractor. Hanya admin yang bisa menghapus.</p><h3 id="repair" tabindex="-1">Repair <a class="header-anchor" href="#repair" aria-label="Permalink to &quot;Repair&quot;">​</a></h3><p>Semua role (admin, user, mekanik) bisa membuat repair. Hanya admin dan mekanik yang bisa edit.</p><h2 id="gps-monitoring" tabindex="-1">GPS &amp; Monitoring <a class="header-anchor" href="#gps-monitoring" aria-label="Permalink to &quot;GPS &amp; Monitoring&quot;">​</a></h2><h3 id="auto-mapping-wialon" tabindex="-1">Auto Mapping Wialon <a class="header-anchor" href="#auto-mapping-wialon" aria-label="Permalink to &quot;Auto Mapping Wialon&quot;">​</a></h3><p>Di Master Truck, klik <strong>Auto Mapping Wialon</strong> untuk otomatis mengisi <code>wialon_unit_id</code> berdasarkan pencocokan plat nomor dengan unit di Wialon.</p><h3 id="geofence-tracking" tabindex="-1">Geofence Tracking <a class="header-anchor" href="#geofence-tracking" aria-label="Permalink to &quot;Geofence Tracking&quot;">​</a></h3><p>Tracking otomatis berjalan di background:</p><ul><li>Sistem polling Wialon setiap 60 detik</li><li>Jika truck masuk geofence yang di-mapping ke route step, dicatat otomatis</li><li>Setelah semua step selesai dan truck masuk finish geofence, dicatat &quot;Finish Order&quot;</li></ul><h3 id="troubleshooting-gps" tabindex="-1">Troubleshooting GPS <a class="header-anchor" href="#troubleshooting-gps" aria-label="Permalink to &quot;Troubleshooting GPS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Masalah</th><th>Solusi</th></tr></thead><tbody><tr><td>Truck tidak muncul di peta</td><td>Cek apakah truck aktif dan punya <code>wialon_unit_id</code></td></tr><tr><td>Semua truck offline</td><td>Cek token Wialon di backend <code>.env</code></td></tr><tr><td>Alamat tidak muncul</td><td>Cek quota Geoapify atau clear localStorage</td></tr><tr><td>Mileage &quot;Invalid GPS Mapping&quot;</td><td>Jalankan Auto Mapping ulang</td></tr></tbody></table><h2 id="keamanan-best-practices" tabindex="-1">Keamanan &amp; Best Practices <a class="header-anchor" href="#keamanan-best-practices" aria-label="Permalink to &quot;Keamanan &amp; Best Practices&quot;">​</a></h2><h3 id="password" tabindex="-1">Password <a class="header-anchor" href="#password" aria-label="Permalink to &quot;Password&quot;">​</a></h3><ul><li>Gunakan password kuat untuk semua akun</li><li>Rotasi password secara berkala</li><li>Jangan share akun antar pengguna</li></ul><h3 id="data-integrity" tabindex="-1">Data Integrity <a class="header-anchor" href="#data-integrity" aria-label="Permalink to &quot;Data Integrity&quot;">​</a></h3><ul><li>Validasi data sebelum import</li><li>Gunakan Nonaktifkan (bukan Hapus) untuk truck/driver yang masih punya history</li><li>Backup database secara rutin</li></ul><h3 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h3><ul><li>Perhatikan siapa yang membuat/mengubah transaksi</li><li>Cek notifikasi untuk aktivitas penting</li><li>Review data secara berkala untuk konsistensi</li></ul><h2 id="troubleshooting-admin" tabindex="-1">Troubleshooting Admin <a class="header-anchor" href="#troubleshooting-admin" aria-label="Permalink to &quot;Troubleshooting Admin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Masalah</th><th>Solusi</th></tr></thead><tbody><tr><td>User tidak bisa login</td><td>Verifikasi username/password, cek status akun</td></tr><tr><td>User tidak bisa akses menu</td><td>Cek level/role user di Master Admin</td></tr><tr><td>Data tidak tersimpan</td><td>Cek validasi input, pastikan field wajib terisi</td></tr><tr><td>Import gagal</td><td>Cek format Excel sesuai template, pastikan referensi valid</td></tr><tr><td>Grafik dashboard kosong</td><td>Pastikan ada data di periode yang dipilih</td></tr><tr><td>Truck tidak muncul di dropdown</td><td>Cek apakah truck berstatus Aktif</td></tr><tr><td>Driver tidak muncul di dropdown</td><td>Cek apakah driver berstatus Aktif</td></tr></tbody></table>',82)])])}const m=t(n,[["render",o]]);export{c as __pageData,m as default};
